export function render(user, options = {}) {
  const greeting = options.formal === true ? "Dear" : "Hi";
  return `${greeting} ${user.name}`;
}

import test from "node:test";
import assert from "node:assert/strict";
import { render } from "../lib/render.mjs";

test("informal greeting", () => {
  assert.equal(render({ name: "ada" }), "Hi ada");
});

test("formal greeting", () => {
  assert.equal(render({ name: "ada" }, { formal: true }), "Dear ada");
});

test("options without formal flag stay informal", () => {
  assert.equal(render({ name: "ada" }, {}), "Hi ada");
  assert.equal(render({ name: "ada" }, { formal: false }), "Hi ada");
});
